insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_3_v1'
from (values
('128.4.b.1.A',2,'During a partner talk, a second grader shows active listening by:','["paraphrasing what the partner said before answering", "repeating the question loudly", "interrupting with a new topic", "looking at the clock"]'::jsonb,0,'Active listeners respond to what was said.','original'),
('128.4.b.1.A',2,'A relevant question to clarify a classmate''s explanation is:','["What is for lunch?", "What did you mean by that word?", "Can I borrow a pencil?", "Is it time for recess?"]'::jsonb,1,'Clarifying questions relate to the speaker''s information.','original'),
('128.4.b.1.B',2,'A second grader gives oral instructions for drawing a house. The best instructions are:','["given all at once in a jumble", "given in a mumble", "given in a clear, related sequence", "given only by pointing"]'::jsonb,2,'Instructions follow a sequence.','original'),
('128.4.b.1.B',2,'To restate an instruction you should:','["repeat the last word only", "forget the first step", "ask someone else to do it", "say it back using your own words"]'::jsonb,3,'Restating shows understanding.','original'),
('128.4.b.1.C',2,'When sharing ideas about a topic, a speaker should speak at:','["a pace and volume that listeners can follow", "a shout", "a whisper", "a mumble"]'::jsonb,0,'Speak clearly at an appropriate pace.','original'),
('128.4.b.1.C',2,'A good speaker keeps comments focused on:','["a favorite game", "the topic under discussion", "last night''s TV show", "a different subject"]'::jsonb,1,'Stay on topic.','original'),
('128.4.b.1.D',2,'One rule for a group discussion is to:','["move away from the group", "ignore ideas you dislike", "take turns and build on what others say", "talk all the time"]'::jsonb,2,'Group rules support collaboration.','original'),
('128.4.b.1.D',2,'When a group disagrees, the group should:','["shout louder", "pick the loudest voice", "end the project", "listen politely to each view"]'::jsonb,3,'Following discussion rules means respecting others.','original'),
('128.4.b.1.E',2,'Asking tells someone you want information. Telling:','["gives information or an instruction", "ends with a question mark", "has no meaning", "always asks a question"]'::jsonb,0,'Social communication includes asking and telling.','original'),
('128.4.b.1.E',2,'Which sentence is an example of telling?','["Who closed the door?", "Please close the door.", "Can you close the door?", "Why is the door open?"]'::jsonb,1,'A direct statement or command tells.','original'),
('128.4.b.10.A',3,'If an author writes to teach readers how volcanoes erupt, the author''s purpose is to:','["persuade", "scare", "inform", "entertain"]'::jsonb,2,'Informational text teaches.','original'),
('128.4.b.10.A',3,'A silly poem about a dancing frog was most likely written to:','["inform about frogs", "give a recipe", "persuade you to buy", "entertain"]'::jsonb,3,'Humor suggests entertaining.','original'),
('128.4.b.10.B',3,'An author explains what happened and why it happened. This text structure is:','["cause and effect", "list", "rhyme", "dialogue"]'::jsonb,0,'Cause and effect tells what happened and why.','original'),
('128.4.b.10.B',3,'An author puts the steps for baking bread in order. This helps the author''s purpose of:','["entertaining with jokes", "teaching a process", "creating suspense", "hiding facts"]'::jsonb,1,'Sequence supports instruction.','original'),
('128.4.b.10.C',2,'Why does an author add a diagram to a science text?','["to hide the title", "to fill the page", "to show how something works", "to decorate the cover"]'::jsonb,2,'Graphics help explain information.','original'),
('128.4.b.10.C',3,'Bold headings and captions are used to:','["make the book heavy", "hide the facts", "decorate the book", "organize and explain information"]'::jsonb,3,'Print and graphic features have purposes.','original'),
('128.4.b.10.D',3,'Literal language means the words:','["say exactly what they mean", "mean the opposite", "are made up", "are a joke"]'::jsonb,0,'Literal language is plain.','original'),
('128.4.b.10.D',3,'Which phrase is figurative language?','["El pan es blanco.", "Estoy muerto de hambre.", "Comí pan.", "Tengo hambre."]'::jsonb,1,'Muerto de hambre is an expression, not literal.','original'),
('128.4.b.10.E',2,'A narrator who tells the story with the words yo and mi uses:','["third person", "second person", "first person", "no person"]'::jsonb,2,'First person uses I.','original'),
('128.4.b.10.E',2,'A story about Pedro told with the words él and su uses:','["fourth person", "first person", "second person", "third person"]'::jsonb,3,'Third person tells about others.','original'),
('128.4.b.10.F',3,'An author repeats a phrase at the end of each stanza to:','["emphasize an idea or create rhythm", "fill space", "end the poem sooner", "hide the meaning"]'::jsonb,0,'Repetition emphasizes ideas.','original'),
('128.4.b.10.F',3,'Repetition in a text means that:','["each word is new", "words or ideas appear again", "the text is short", "the text has no words"]'::jsonb,1,'Repetition repeats elements.','original'),
('128.4.b.11.A',2,'Which is a way to plan a first draft?','["write the last sentence first", "copy a page", "brainstorm ideas in a list", "erase your notes"]'::jsonb,2,'Planning generates ideas.','original'),
('128.4.b.11.A',2,'A student draws a picture of a trip before writing about it. This is:','["editing", "publishing", "revising", "planning"]'::jsonb,3,'Drawing can be planning.','original'),
('128.4.b.11.B.i',3,'Organizing a paragraph with structure means:','["putting sentences in a logical order", "using no sentences", "writing at random", "skipping the topic"]'::jsonb,0,'Structure organizes.','original'),
('128.4.b.11.B.i',3,'A piece of writing that has an introduction, body and conclusion shows:','["a spelling list", "organization", "a dictionary", "a rhyme"]'::jsonb,1,'Organization groups ideas.','original'),
('128.4.b.11.B.ii',3,'Which detail best develops the idea My cat is playful?','["She is a cat.", "Cats sleep.", "She chases a string across the floor every morning.", "I have a cat."]'::jsonb,2,'Specific details develop ideas.','original'),
('128.4.b.11.B.ii',3,'Relevant details are details that:','["are about something else", "are the longest", "change the topic", "support the main idea"]'::jsonb,3,'Relevant means connected to the idea.','original'),
('128.4.b.11.C',3,'To revise a draft you may:','["add, delete or rearrange sentences", "hide the draft", "count the words only", "trace the letters"]'::jsonb,0,'Revision changes content.','original'),
('128.4.b.11.C',3,'A sentence does not fit the topic of your paragraph. In revision you should:','["add more like it", "delete it", "copy it twice", "underline it"]'::jsonb,1,'Delete off-topic text.','original'),
('128.4.b.11.D.i',3,'The subject of a sentence tells:','["where the action ends", "how long the sentence is", "who or what does the action", "when the sentence ends"]'::jsonb,2,'The subject names who does the action.','original'),
('128.4.b.11.D.ii',3,'Which sentence is in the future tense?','["Ayer fui al parque.", "Siempre voy al parque.", "Hoy voy al parque.", "Mañana iré al parque."]'::jsonb,3,'Mañana points to the future.','original'),
('128.4.b.11.D.ii',3,'Which sentence correctly uses estar for how someone feels right now?','["Mi mamá está contenta.", "Mi mamá es de México.", "Mi mamá es doctora.", "Mi mamá es alta."]'::jsonb,0,'Estar tells temporary feelings or conditions.','original'),
('128.4.b.11.D.iii',2,'Which noun is a proper noun?','["montaña", "Texas", "estado", "río"]'::jsonb,1,'Proper nouns name particular places.','original'),
('128.4.b.11.D.iii',2,'Which pair is correct?','["los flores", "el flores", "las flores", "la flores"]'::jsonb,2,'Plural feminine uses las.','original'),
('128.4.b.11.D.iv',2,'Which phrase has agreement between the adjective and the noun?','["unas gatos negros", "un gatos negro", "unos gatos negra", "unos gatos negros"]'::jsonb,3,'Articles and adjectives match the noun.','original'),
('128.4.b.11.D.iv',2,'Which kind of word is grande in the phrase la casa grande?','["adjective", "preposition", "pronoun", "verb"]'::jsonb,0,'Grande describes casa.','original'),
('128.4.b.11.D.ix',2,'In the closing Con cariño, which words begin with capital letters?','["every word", "only the first word", "no word", "only the last word"]'::jsonb,1,'The first word of a closing is capitalized.','original'),
('128.4.b.11.D.ix',2,'Proper nouns such as city names are written with:','["no vowels", "all lowercase letters", "a capital first letter", "a number first"]'::jsonb,2,'Names of cities begin with a capital letter.','original'),
('128.4.b.11.D.v',3,'Which adverb tells where?','["siempre", "pronto", "ayer", "aquí"]'::jsonb,3,'Aquí tells place.','original'),
('128.4.b.11.D.v',3,'Which adverb tells when?','["ahora", "allá", "lejos", "cerca"]'::jsonb,0,'Ahora tells time.','original'),
('128.4.b.11.D.vi',3,'Phrases like en la mesa and sobre el techo start with which kind of word?','["a verb", "a preposition", "an adjective", "a period"]'::jsonb,1,'A preposition plus its object forms the phrase.','original'),
('128.4.b.11.D.vii',3,'Which pronoun replaces Ana in Ana canta?','["Él", "Yo", "Ella", "Ellos"]'::jsonb,2,'Ella stands for a female person.','original'),
('128.4.b.11.D.vii',3,'In Dame el libro, the pronoun me in dame is an object pronoun that means:','["from you", "by us", "of them", "to me"]'::jsonb,3,'Object pronouns show who receives the action.','original'),
('128.4.b.11.D.viii',3,'What do coordinating conjunctions do in a sentence?','["join words, phrases or parts of a sentence", "show a number", "name a place", "end the sentence"]'::jsonb,0,'Conjunctions join words and phrases.','original'),
('128.4.b.11.D.viii',3,'Which sentence has a compound predicate?','["Luis baila bien.", "Ana canta y baila.", "Ana canta.", "Ana y Luis cantan."]'::jsonb,1,'Two actions share one subject.','original'),
('128.4.b.11.D.x',3,'Which sentence begins correctly with an opening exclamation mark?','["Cuidado con el perro!", "¡Cuidado con el perro", "¡Cuidado con el perro!", "Cuidado con el perro¡"]'::jsonb,2,'Spanish exclamations use ¡ and !.','original'),
('128.4.b.11.D.x',2,'Which punctuation mark ends a telling sentence?','["a comma", "a question mark", "an exclamation mark", "a period"]'::jsonb,3,'Telling sentences end with a period.','original'),
('128.4.b.11.D.xi',3,'Which spelling of the word for a two-wheeled ride is correct?','["bicicleta", "bisicleta", "bicicletta", "visicleta"]'::jsonb,0,'Bicicleta uses b and c.','original'),
('128.4.b.11.D.xi',3,'Which spelling names the tall animal with a long neck?','["jiraffa", "jirafa", "girafa", "hirafa"]'::jsonb,1,'Jirafa uses j before i.','original'),
('128.4.b.11.E',2,'Publishing your writing means:','["starting over", "hiding the draft", "preparing a final copy and sharing it", "throwing it away"]'::jsonb,2,'Publishing shares finished work.','original'),
('128.4.b.11.E',2,'A way to share a published story is to:','["lock it in a drawer", "ignore it", "tear it up", "read it aloud to the class"]'::jsonb,3,'Sharing gives writing an audience.','original'),
('128.4.b.12.A',3,'A poem is a type of:','["literary text", "correspondence", "procedural text", "report"]'::jsonb,0,'Poetry is literary.','original'),
('128.4.b.12.A',3,'A personal narrative should be told:','["from a recipe", "from your own experience", "from a map", "from someone else''s life"]'::jsonb,1,'Personal narratives are first-hand.','original'),
('128.4.b.12.B',3,'A report is an example of:','["a letter", "a fable", "informational text", "a poem"]'::jsonb,2,'Reports present facts.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
