('128.4.b.2.A.iv',3,'A diphthong is:','["two vowels that form one syllable", "a consonant pair", "two vowels in separate syllables", "a silent letter"]'::jsonb,0,'Diphthongs are single syllables.','original'),
('128.4.b.2.A.iv',3,'Which word has a hiatus, with two vowels in separate syllables?','["aire", "país", "bueno", "cuatro"]'::jsonb,1,'Pa-ís has two syllables.','original'),
