('128.4.b.2.B.iii',2,'Which is the correct abbreviation for usted?','["Ut.", "Ud.", "Us.", "Ud,"]'::jsonb,1,'Ud. abbreviates usted.','original'),
('128.4.b.2.B.iii',2,'The abbreviation for calle is often written:','["cy", "cl", "c/", "ca."]'::jsonb,2,'C/ is a common abbreviation for calle.','original'),
