('128.4.b.2.B.iv',3,'Which word is spelled correctly with the suffix -ción?','["canción", "cancion", "cansión", "canción''"]'::jsonb,0,'Words with -ción take an accent.','original'),
('128.4.b.2.B.v',3,'Which word is spelled correctly with qui?','["kitar", "quitar", "citar", "cuitar"]'::jsonb,1,'Quitar uses qui.','original'),
